package com.wini.owle.entity.runs

import com.wini.owle.entity.TestInputs
import org.jetbrains.exposed.dao.LongEntity
import org.jetbrains.exposed.dao.LongEntityClass
import org.jetbrains.exposed.dao.id.EntityID

/**
 * Defines an input value for a test case, which specifies values for data points
 * required by the workflow or step being tested. Inputs can be user-defined or
 * generated by an AI model.
 */
class TestInputDao(id: EntityID<Long>) : LongEntity(id) {
    companion object : LongEntityClass<TestInputDao>(TestInputs)

    /**
     * Relationship to the associated test case.
     */
    var testCase by TestCaseDao referencedOn TestInputs.testCase

    /**
     * Name of the data point this input corresponds to.
     */
    var dataPointName by TestInputs.dataPointName

    /**
     * Value assigned to the data point for the test case.
     */
    var value by TestInputs.value

    /**
     * Specifies how the value was generated, either manually or by an AI model.
     */
    var generationMethod by TestInputs.generationMethod
}